// Next.js requires route-segment-config exports like `dynamicParams` to be
// a literal boolean statically analyzable in the route file itself -- it
// cannot be a computed expression (e.g. reading `process.env`), so the
// same source file cannot directly serve both deployment targets:
// `dynamicParams: true` (needed for `next dev` / a real server deployment
// to render real, non-dummy lot IDs on demand) and `dynamicParams: false`
// (required by `output: "export"`, which has no server to render
// anything on demand and therefore only ever supports the lot IDs
// pre-generated by `generateStaticParams`).
//
// This script temporarily flips the literal to `false` for the Cloudflare
// static export build only, then restores the checked-in `true` value
// afterward regardless of build outcome, so the working tree is never
// left modified by a local `build:cloudflare` run.
import { spawn } from "node:child_process";
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const pageFile = fileURLToPath(
  new URL("../app/[locale]/lots/[lotId]/page.tsx", import.meta.url),
);

const DYNAMIC_TRUE = "export const dynamicParams = true;";
const DYNAMIC_FALSE = "export const dynamicParams = false;";

const originalContent = await readFile(pageFile, "utf8");
if (!originalContent.includes(DYNAMIC_TRUE)) {
  throw new Error(
    `Expected "${DYNAMIC_TRUE}" in ${pageFile} -- update this script if that line changed.`,
  );
}

await writeFile(pageFile, originalContent.replace(DYNAMIC_TRUE, DYNAMIC_FALSE));

try {
  const exitCode = await runNextBuild();
  process.exitCode = exitCode;
} finally {
  await writeFile(pageFile, originalContent);
}

function runNextBuild() {
  return new Promise((resolve, reject) => {
    const child = spawn("npx next build", {
      env: { ...process.env, CLOUDFLARE_PAGES: "true" },
      shell: true,
      stdio: "inherit",
    });
    child.on("error", reject);
    child.on("close", (code) => resolve(code ?? 1));
  });
}
